"""reactB ctrl.py: Boey (56484772) programme for days 0-10, circuit executor (circ_v13 params) from HANDOVER.

Prefix = a tree over 102 recorded Boey games (lib/prefix.json.gz: actions steps 0..287, day-start tile layouts).
Boey's controller is layout-deterministic through d3 (90/102 games identical) and branches on the shops from d3.
We follow one recorded game at a time; on SWITCH_DAYS at h0 we may move to another recorded game only if its day-start
layout (tile codes + planting days) is identical to ours, choosing by shop-sequence match, then shop signature, then bank.
Repairs: PLANT trim to seeds held, cash guard (sell shed stock ahead of scheduled purchases), weed/obstacle-safe.
Bench form: src:ctrl.py|{json}. Build fills _LIB_B64 / _CIRC_B64 (embedded)."""
import json, os, math, gzip, zlib, base64, types, collections

P = {'HANDOVER': 264, 'SWITCH_DAYS': [3, 6], 'PD_TOL': 0, 'W_SHOP': 2.0, 'W_NEX': 3.0, 'W_MONEY': 300.0, 'W_STAY': 2.0,
     'W_BANK': 1e-5, 'T0': None, 'GUARD': False, 'GUARD_HORIZON': 48, 'PLANT_TRIM': True, 'XC_P': {}, 'EXCL': [],
     'NET': False, 'HFIRST': False, 'HFUND': False, 'HFUND_KEEP': {'WHEAT': 1.0, 'FERTILIZER': 0}, 'RES': False, 'RES_R0': 60, 'RES_HIRE': True, 'RES_FEED': True, 'RES_FROM_DAY': 1, 'RESCUE': True, 'RESCUE_HOUR': 17, 'RESCUE_ANY_HOUR': 21, 'LAND_RETRY': True, 'ACAP': False, 'ACAP_A': {'SHEEP': [3.0, 7.0], 'COW': [4.5, 3.2], 'GOOSE': [6.0, 2.0]}, 'MATCH': 'lenient', 'W_ANIMAL': 1.5, 'W_OURS': 1.0, 'TOL': 1, 'DEBT': False, 'DEBT_LAST_DAY': 10, 'TRUNK': 0.0, 'TRUNK_ISO': None, 'TRUNK_WIN': 1.0, 'TRUNK_TOL': 1.0, 'RESCUE_KEEP': False, 'LOG': bool(os.environ.get('RB_LOG'))}
P.update({"RESCUE": True, "HFIRST": True, "HFUND": True})
P.update({'XC_P': {'LATE_RATIO': 1.15, 'SPEC_MARGIN': 1000000000.0}, 'TRUNK': 1.0, 'TRUNK_ISO': 0.05, 'W_STAY': 0.0, 'RESCUE_KEEP': True})
P.update({'FP': False, 'FP_DAYS': [1, 2, 3], 'FP_TOL': 3.0})
P.update({'OV_STRAW': 0, 'OV_DAYS': [3, 4, 5], 'OV_KINDS': ['COW', 'SHEEP']})
P.update({'XC_P': {'LATE_RATIO': 1.15, 'SPEC_MARGIN': 1000000000.0, 'FIN_FIX': True, 'HIRE_DOWN': True, 'HIRE_DOWN_W': 1.2, 'MELON_EARLY': True, 'FERT_WHEAT_MAXP': 120, 'FERT_BUY_MAXP': 120, 'FILL': 1, 'FILL_HD': True, 'XFILL': True, 'AH_V': 0.3, 'LATE_HARVEST_W': 0.1, 'SELLS_FIRST': True, 'DIG_DEP': True, 'ASSIGN3': True, 'PLAN_H1ALL': True, 'H0EST': True, 'REORDER': True, 'LOADFIX': True, 'CREDIT': True, 'MIDDROP_LAST': True, 'MD_MIN': 2}})
_LIB_B64 = ""
_CIRC_B64 = ""
try: HERE = os.path.dirname(os.path.abspath(__file__))
except NameError: HERE = '.'
if not os.path.isdir(os.path.join(HERE, 'lib')) and os.path.isdir(os.path.join(HERE, '..', 'lib')): HERE = os.path.normpath(os.path.join(HERE, '..'))
SHOPS = {'BAKERY': ['EGG', 'WHEAT'], 'PIZZA_SHOP': ['MILK', 'TOMATO', 'WHEAT'], 'BRUNCH_SPOT': ['EGG', 'WHEAT', 'STRAWBERRY'], 'YARN_STORE': ['WOOL'],
         'ICE_CREAM_SHOP': ['STRAWBERRY', 'MILK', 'WHEAT'], 'PET_CAFE': ['CARROT'], 'SMOOTHIE_SHOP': ['STRAWBERRY', 'MILK'],
         'FARMERS_MARKET': ['WHEAT', 'CARROT', 'TOMATO', 'STRAWBERRY']}
SIG_ITEMS = ('STRAWBERRY', 'WOOL', 'MILK', 'TOMATO', 'CARROT', 'EGG')
ITEMS = ('WHEAT', 'CARROT', 'TOMATO', 'STRAWBERRY', 'MELON', 'EGG', 'MILK', 'WOOL', 'FERTILIZER', 'GOOSE', 'COW', 'SHEEP')
SEED_COST = {'WHEAT': 10, 'CARROT': 20, 'TOMATO': 50, 'STRAWBERRY': 100, 'MELON': 80}
ANIMAL_COST = {'GOOSE': 300, 'COW': 400, 'SHEEP': 500}
S = {}
_G = {'lib': None, 'xc': None, 'xcp': None}

def _log(m):
    if P['LOG']: open(os.environ.get('RB_LOGFILE', '/tmp/reactB.log'), 'a').write(m + '\n')

def sig(shops):
    c = collections.Counter()
    for s in shops:
        for p in SHOPS[s]: c[p] += 2 if len(SHOPS[s]) == 1 else 1
    return tuple(c[p] for p in SIG_ITEMS)

def lib():
    if _G['lib'] is None:
        if _LIB_B64: raw = zlib.decompress(base64.b64decode(_LIB_B64))
        else: raw = gzip.open(os.path.join(HERE, 'lib', P.get('LIBFILE', 'prefix.json.gz'))).read()
        L = [t for t in json.loads(raw) if t['ep'] not in set(P['EXCL'])]
        for t in L:
            t['sig'] = [sig(t['shops'][:k]) for k in range(9)]
            if isinstance(t['a'], str): t['a_raw'] = t.pop('a')
        _G['lib'] = L
    return _G['lib']

def xc():
    if _G['xc'] is None:
        if _CIRC_B64:
            m = types.ModuleType('rb_circuit'); src = zlib.decompress(base64.b64decode(_CIRC_B64)).decode()
            exec(compile(src, 'rb_circuit', 'exec'), m.__dict__)
            _G['xcp'] = json.loads(zlib.decompress(base64.b64decode(_XCP_B64)).decode())
        else:
            import importlib.util
            spec = importlib.util.spec_from_file_location('rb_circuit_%d' % os.getpid(), os.path.join(HERE, 'circuit.py'))
            m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
            _G['xcp'] = json.load(open(os.path.join(HERE, 'circ_v13_params.json')))
        _G['xc'] = m
    return _G['xc']
_XCP_B64 = ""

def tcode(t):
    if t is None: return '.'
    if isinstance(t, str): return '#'
    k = t.get('kind')
    if k == 'PLANT': return t['crop'][0]
    if k == 'PASTURE': return {'COW': 'c', 'SHEEP': 's'}.get(t.get('animal'), 'p')
    if k == 'COOP': return 'g' if t.get('animal') else 'o'
    return '?'

def enc(obs):
    f = obs['farms'][obs['player']]; flat = [t for r in f['tiles'] for t in r]
    return ''.join(tcode(t) for t in flat), [(-1 if not isinstance(t, dict) or t.get('kind') != 'PLANT' else t.get('planted_day', -1)) for t in flat], f['money']

def layout_ok(t, day, tiles, pd):
    if day >= len(t['st']): return False
    tt, tp, _ = t['st'][day]
    if tt != tiles: return False
    tol = P['PD_TOL']
    return all(a < 0 or abs(a - b) <= tol for a, b in zip(pd, tp))

def score(t, day, money, known, cur):
    k = len(known); d = 0.
    if t['shops'][:k] != known:
        d += P['W_NEX'] + P['W_SHOP'] * sum(abs(x - y) for x, y in zip(t['sig'][k], sig(known)))
    tm = t['st'][day][2]
    if money < tm: d += (tm - money) / P['W_MONEY']
    if cur is not None and t['ep'] == cur['ep']: d -= P['W_STAY']
    d -= P['W_BANK'] * t['bank']
    return d

def acts_of(t):
    if 'a' not in t: t['a'] = json.loads(t.pop('a_raw'))
    return t['a']

def choose0():
    L = lib()
    if P['T0']:
        for t in L:
            if t['ep'] == P['T0']: return t
    modal = collections.Counter(t['st'][3][0] for t in L).most_common(1)[0][0]
    return max([t for t in L if t['st'][3][0] == modal], key=lambda t: t['bank'])

ANIM = set('csgpo')
def ldist(t, day, tiles, pd):
    """lenient layout distance: tile mismatches (animals W_ANIMAL; tiles we have planted/stocked but the tape does not: +W_OURS,
    they would be neglected by the tape's units), planting-day differences beyond TOL: 0.5."""
    tt, tp, _ = t['st'][day]; d = 0.
    for i in range(100):
        a = tiles[i]; b = tt[i]
        if a != b:
            d += P['W_ANIMAL'] if (a in ANIM or b in ANIM) else 1.
            if a not in '.#?': d += P['W_OURS']
        elif pd[i] >= 0 and abs(pd[i] - tp[i]) > P['TOL']: d += 0.5
    return d

_TC = {}
def trunk_adj(sc, L, day, known):
    """prefer candidates whose layout at the next switch day is shared (ldist <= TRUNK_TOL) by many tapes with our shop prefix,
    so the next switch can branch into the matching world instead of being stuck on an isolated tape."""
    nx = [d for d in P['SWITCH_DAYS'] if d > day]
    if not nx: return sc
    nd = min(nx); k = len(known)
    pool = [u for u in L if u['shops'][:k] == known and nd < len(u['st'])]
    if len(pool) < 3: return sc
    best = min(x[0] for x in sc); out = []
    if P['TRUNK_ISO'] is not None:
        t = L[min(sc)[2]]
        if nd < len(t['st']):
            tl, pd, _ = t['st'][nd]
            if sum(ldist(u, nd, tl, pd) <= P['TRUNK_TOL'] for u in pool if u is not t) / (len(pool) - 1) > P['TRUNK_ISO']: return sc
    for d, b, i in sc:
        t = L[i]
        if d <= best + P['TRUNK_WIN'] and nd < len(t['st']):
            key = (t['ep'], nd, tuple(known))
            if key not in _TC:
                tl, pd, _ = t['st'][nd]
                _TC[key] = sum(ldist(u, nd, tl, pd) <= P['TRUNK_TOL'] for u in pool if u is not t) / (len(pool) - 1)
            d = d - P['TRUNK'] * _TC[key]
        out.append((d, b, i))
    return out

def choose(obs, day, known, cur):
    tiles, pd, money = enc(obs)
    if P['MATCH'] == 'lenient':
        L = [t for t in lib() if day < len(t['st'])]
        sc = [(ldist(t, day, tiles, pd) + score(t, day, money, known, cur), -t['bank'], i) for i, t in enumerate(L)]
        if P.get('TRUNK'): sc = trunk_adj(sc, L, day, known)
        if P.get('RANK') and str(day) in P['RANK']: sc.sort(); d, _, i = sc[min(P['RANK'][str(day)], len(sc) - 1)]; return L[i], d, len(L)
        d, _, i = min(sc); return L[i], d, len(L)
    cands = [t for t in lib() if layout_ok(t, day, tiles, pd)]
    if not cands: return cur, None, 0
    best = min(cands, key=lambda t: score(t, day, money, known, cur))
    return best, score(best, day, money, known, cur), len(cands)

def fib(n):
    a = b = 1
    for _ in range(n): a, b = b, a + b
    return a

def budget_guard(obs, action, step, tape):
    me = obs['farms'][obs['player']]; priv = obs['private']; shed = priv['shed']; prices = obs['market']['prices']
    balance = {p: 0 for p in ITEMS}; reserve = {p: 0 for p in ITEMS}; hires = {}; budget = 0.
    quadrants = len(me['unlocked_quadrants'])
    for t in range(step, min(len(tape), step + P['GUARD_HORIZON'])):
        fa, ha, ma = tape[t]
        for op in [fa, *ha]:
            if not op: continue
            item = 'WHEAT' if op[0] == 'FEED' else 'FERTILIZER' if op[0] == 'FERTILIZE' else op[1] if op[0] == 'PLACE' and len(op) > 1 else None
            if item in balance:
                n = max(1, op[2]) if op[0] == 'PLACE' and len(op) > 2 and isinstance(op[2], int) else 1
                balance[item] -= n; reserve[item] = max(reserve[item], -balance[item])
        for o in ma:
            if not o: continue
            op = o[0]; n = max(1, o[2]) if len(o) > 2 and isinstance(o[2], int) else 1
            if op == 'HIRE':
                d = (t - step) // 24; hires[d] = hires.get(d, 0) + 1
            elif op == 'BUY_LAND' and quadrants < 4:
                budget += [1000, 2000, 4000][quadrants - 1]; quadrants += 1
            elif op == 'BUY_SEED' and o[1] in SEED_COST: budget += SEED_COST[o[1]] * n
            elif op == 'BUY_PRODUCT' and o[1] in prices: budget += prices[o[1]] * n; balance[o[1]] += n
            elif op == 'BUY_ANIMAL' and o[1] in ANIMAL_COST: budget += ANIMAL_COST[o[1]] * n; balance[o[1]] += n
            elif op == 'SELL' and o[1] in prices and t > step: budget -= 0  # future tape sells are not counted as cash
    for d, n in hires.items():
        first = me['hires_today'] if d == 0 else 0
        budget += sum(fib(first + i) for i in range(n))
    orders = action['market']
    existing = {p: sum(o[2] for o in orders if o[0] == 'SELL' and o[1] == p and len(o) > 2 and isinstance(o[2], int) and o[2] > 0) for p in ITEMS[:9]}
    cash = me['money'] + sum(min(shed.get(p, 0), existing[p]) * prices[p] for p in ITEMS[:9])
    short = budget - cash
    if short <= 0: return
    cand = []
    for i, p in enumerate(ITEMS[:9]):
        carried = sum(max(0, inv.get(p, 0)) for inv in priv['inventories'])
        avail = max(0, shed.get(p, 0) - max(0, reserve[p] - carried) - existing[p])
        if avail > 0 and prices[p] >= 2: cand.append((-prices[p], i, p, avail))
    added = False
    for neg, _, p, n in sorted(cand):
        if short <= 0: break
        q = min(n, math.ceil(short / -neg)); prev = next((o for o in orders if o[0] == 'SELL' and o[1] == p), None)
        if prev is not None: prev[2] += q
        elif len(orders) < 10: orders.append(['SELL', p, q])
        else: continue
        short -= q * -neg; added = True
    if added: orders.sort(key=lambda o: o[0] != 'SELL')

def net_orders(ma):
    """Net same-step BUY_PRODUCT/SELL of WHEAT/FERTILIZER (Boey's churn) into one order at the position of the first one."""
    b = collections.Counter(); se = collections.Counter()
    for o in ma:
        if len(o) > 2 and isinstance(o[2], int) and o[1] in ('WHEAT', 'FERTILIZER'):
            if o[0] == 'BUY_PRODUCT': b[o[1]] += o[2]
            elif o[0] == 'SELL': se[o[1]] += o[2]
    out = []; done = set()
    for o in ma:
        if len(o) > 2 and o[1] in ('WHEAT', 'FERTILIZER') and o[0] in ('BUY_PRODUCT', 'SELL') and b[o[1]] and se[o[1]]:
            if o[1] in done: continue
            done.add(o[1]); n = b[o[1]] - se[o[1]]
            if n > 0: out.append(['BUY_PRODUCT', o[1], n])
            elif n < 0: out.append(['SELL', o[1], -n])
        else: out.append(o)
    return out

NOOP_ON_EMPTY = ('WATER', 'FERTILIZE', 'HARVEST', 'FEED', 'CARE', 'COLLECT_FERTILIZER', 'PASS', 'DIG')
def repair(obs, action, day):
    """PLANT trim to seeds held; missed plants (no seed / weed on tile) become a debt re-planted by the next unit whose
    tape action on that tile is a no-op; the missing seeds are bought now."""
    me = obs['farms'][obs['player']]; tiles = me['tiles']
    seeds = dict(obs['private'].get('seeds', {})); debt = S.setdefault('debt', {}); need = collections.Counter()
    units = [action['farmer']] + action['hands']
    pos = [tuple(me['farmer'])] + [tuple(h) for h in me['hands']]
    for q in list(debt):
        t = tiles[q[1]][q[0]]
        if t is not None and not (isinstance(t, dict) and t.get('kind') == 'WEED'): del debt[q]
    for i, u in enumerate(units):
        if i >= len(pos): break
        x, y = pos[i]; t = tiles[y][x]
        if len(u) >= 2 and u[0] == 'PLANT':
            if isinstance(t, dict) and t.get('kind') == 'WEED' and P['DEBT']:
                debt[(x, y)] = u[1]; u[:] = ['DIG']
                continue
            if seeds.get(u[1], 0) > 0: seeds[u[1]] -= 1; debt.pop((x, y), None)
            else:
                if P['DEBT'] and t is None: debt[(x, y)] = u[1]; need[u[1]] += 1
                u[:] = ['PASS']
        elif P['DEBT'] and (x, y) in debt and day <= P['DEBT_LAST_DAY'] and (not u or u[0] in NOOP_ON_EMPTY):
            crop = debt[(x, y)]
            if isinstance(t, dict) and t.get('kind') == 'WEED': u[:] = ['DIG']
            elif t is None:
                if seeds.get(crop, 0) > 0: seeds[crop] -= 1; u[:] = ['PLANT', crop]; del debt[(x, y)]; _log(f"d{day} debt plant {crop} at {(x, y)}")
                else: need[crop] += 1
    if need:
        m = action['market']
        for crop, n in need.items():
            if len(m) < 10: m.append(['BUY_SEED', crop, n])

MILK_SHOPS = ('PIZZA_SHOP', 'ICE_CREAM_SHOP', 'SMOOTHIE_SHOP'); EGG_SHOPS = ('BAKERY', 'BRUNCH_SPOT')
def _q(t, day):
    return (100 - t['st'][min(day, len(t['st']) - 1)][0].count('#') + 3) // 25   # 3 of 4 shed-access tiles start locked
def tape_quads(t, step):
    """tape's quadrant count at this step: day-start count, raised to the next day-start count from the hour of the tape's
    first BUY_LAND order of the day (Boey re-issues BUY_LAND every step until it succeeds)."""
    day = step // 24; q = _q(t, day); q1 = _q(t, day + 1)
    if q1 > q and any(o and o[0] == 'BUY_LAND' for s in range(day * 24, step + 1) for o in acts_of(t)[s][2]): return min(3, q1)
    return min(3, q)
def overlay(obs, action, step, acts, known):
    me = obs['farms'][obs['player']]; m = action['market']
    if P['LAND_RETRY']:
        q = len(me['unlocked_quadrants']); tq = tape_quads(S['tape'], step)
        if q < tq and not any(o and o[0] == 'BUY_LAND' for o in m):
            k = len([o for o in m if o and o[0] == 'SELL']); m.insert(k, ['BUY_LAND']); _log(f"s{step} land retry q {q} tape {tq}")
    if P['ACAP']:
        cnt = collections.Counter()
        for r in me['tiles']:
            for t in r:
                if isinstance(t, dict) and t.get('animal'): cnt[t['animal']] += 1
        for k in ANIMAL_COST: cnt[k] += obs['private']['shed'].get(k, 0) + sum(inv.get(k, 0) for inv in obs['private']['inventories'])
        n_sh = {'SHEEP': sum(1 for s in known if s == 'YARN_STORE'), 'COW': sum(1 for s in known if s in MILK_SHOPS), 'GOOSE': sum(1 for s in known if s in EGG_SHOPS)}
        for o in list(m):
            if o and o[0] == 'BUY_ANIMAL' and o[1] in P['ACAP_A']:
                a, b = P['ACAP_A'][o[1]]; cap = int(a + b * n_sh[o[1]])
                room = cap - cnt[o[1]]
                if room <= 0: m.remove(o); _log(f"s{step} acap block {o} cnt {cnt[o[1]]} cap {cap}")
                else:
                    n = min(o[2], room); cnt[o[1]] += n
                    if n < o[2]: o[2] = n

MOVES = {'NORTH': (0, -1), 'SOUTH': (0, 1), 'EAST': (1, 0), 'WEST': (-1, 0)}
SHED_T = [(4, 4), (5, 4), (4, 5), (5, 5)]
USEFUL = ('WATER', 'FEED', 'HARVEST', 'PLANT', 'CARE', 'COLLECT_FERTILIZER', 'FERTILIZE', 'PICKUP', 'PLACE', 'BUILD_COOP', 'BUILD_PASTURE', 'DIG')
def _toward(p, q):
    if p[0] != q[0]: return ['EAST'] if q[0] > p[0] else ['WEST']
    if p[1] != q[1]: return ['SOUTH'] if q[1] > p[1] else ['NORTH']
    return None
def _d(p, q): return abs(p[0] - q[0]) + abs(p[1] - q[1])
def rescue(obs, action, step, acts):
    """Evening safety net: crops that die tonight if not watered and animals that escape tonight if not fed, which the tape's
    remaining actions today (simulated from the units' current positions) do not cover, are served by units taken off the tape
    for the rest of the day (units with no useful tape action left first)."""
    me = obs['farms'][obs['player']]; tiles = me['tiles']; priv = obs['private']; day = step // 24; hour = step % 24
    units = [action['farmer']] + action['hands']
    pos = [tuple(me['farmer'])] + [tuple(h) for h in me['hands']]
    n = min(len(units), len(pos)); end = day * 24 + 24
    R = S.setdefault('resc', {})
    if R.get('day') != day: R.clear(); R['day'] = day; R['who'] = {}
    covered = set(); useful_left = [0] * n; ucov = [[] for _ in range(n)]
    for ui in range(n):
        if ui in R['who']: continue
        p = pos[ui]
        for s in range(step, min(end, len(acts))):
            fa, ha, _ = acts[s]
            a = fa if ui == 0 else (ha[ui - 1] if ui - 1 < len(ha) else None)
            if not a: continue
            if a[0] in MOVES:
                dx, dy = MOVES[a[0]]; q = (p[0] + dx, p[1] + dy)
                if 0 <= q[0] < 10 and 0 <= q[1] < 10: p = q
            elif a[0] in USEFUL:
                useful_left[ui] += 1
                if a[0] in ('WATER', 'FEED'): covered.add((a[0], p)); ucov[ui].append((a[0], p))
    risk = []
    for y in range(10):
        for x in range(10):
            t = tiles[y][x]
            if not isinstance(t, dict): continue
            if t.get('kind') == 'PLANT' and not t.get('watered_today') and t.get('consecutive_unwatered', 0) >= 1 and ('WATER', (x, y)) not in covered:
                risk.append(('WATER', (x, y)))
            elif t.get('animal') and not t.get('fed_today') and t.get('consecutive_unfed', 0) >= 1 and ('FEED', (x, y)) not in covered:
                risk.append(('FEED', (x, y)))
    if P['LOG'] and hour == P['RESCUE_HOUR']:
        cs = [(x, y, tiles[y][x]['crop'][0], tiles[y][x].get('consecutive_unwatered'), tiles[y][x].get('watered_today'), ('WATER', (x, y)) in covered) for y in range(10) for x in range(10) if isinstance(tiles[y][x], dict) and tiles[y][x].get('kind') == 'PLANT' and tiles[y][x].get('crop') == 'STRAWBERRY']
        _log(f"s{step} straw state {cs} hands {n}")
    taken = {tg for q in R['who'].values() for tg in q}
    risk = [r for r in risk if r not in taken]
    hours_left = end - step
    crit = set()
    if P['RESCUE_KEEP']:
        for y in range(10):
            for x in range(10):
                t = tiles[y][x]
                if not isinstance(t, dict): continue
                if t.get('kind') == 'PLANT' and not t.get('watered_today') and t.get('consecutive_unwatered', 0) >= 1: crit.add(('WATER', (x, y)))
                elif t.get('animal') and not t.get('fed_today') and t.get('consecutive_unfed', 0) >= 1: crit.add(('FEED', (x, y)))
    for r in risk:
        free = [ui for ui in range(n) if ui not in R['who'] and (useful_left[ui] == 0 or hour >= P['RESCUE_ANY_HOUR'])]
        if not free: break
        if P['RESCUE_KEEP']:
            # a unit whose own remaining tape waters/feeds a tile that dies tonight keeps that job: rescue r first, then its own
            # targets, only if the whole route fits in the hours left; units without such duties are preferred.
            def cost0(ui):
                c = _d(pos[ui], r[1])
                if r[0] == 'FEED' and (priv['inventories'][ui].get('WHEAT', 0) <= 0 if ui < len(priv['inventories']) else True):
                    sh = min(SHED_T, key=lambda q: _d(pos[ui], q)); c = _d(pos[ui], sh) + 1 + _d(sh, r[1])
                return c
            def route(ui):
                own = [q for q in dict.fromkeys(ucov[ui]) if q in crit and q != r]
                c = cost0(ui) + 1; p = r[1]
                for q in own:
                    c += _d(p, q[1]) + 1; p = q[1]
                return c, own
            best = None
            for ui in free:
                c, own = route(ui)
                if c > hours_left: continue
                key = (len(own) > 0, c)
                if best is None or key < best[0]: best = (key, ui, own)
            if best is None: continue
            _, ui, own = best
            R['who'][ui] = [r] + own
            _log(f"s{step} rescue {r} by unit {ui} (useful left {useful_left[ui]}, keeps {own})")
            continue
        def cost(ui):
            c = _d(pos[ui], r[1])
            if r[0] == 'FEED' and priv['inventories'][ui].get('WHEAT', 0) <= 0 if ui < len(priv['inventories']) else True:
                sh = min(SHED_T, key=lambda q: _d(pos[ui], q)); c = _d(pos[ui], sh) + 1 + _d(sh, r[1])
            return c
        ui = min(free, key=cost)
        if cost(ui) + 1 > hours_left: continue
        R['who'][ui] = [r]
        _log(f"s{step} rescue {r} by unit {ui} (useful left {useful_left[ui]})")
    # drive the rescuers
    need_wheat = 0
    for ui, q in list(R['who'].items()):
        if ui >= n: continue
        while q:
            op, tg = q[0]; t = tiles[tg[1]][tg[0]]
            done = not isinstance(t, dict) or (op == 'WATER' and (t.get('kind') != 'PLANT' or t.get('watered_today'))) or (op == 'FEED' and (not t.get('animal') or t.get('fed_today')))
            if done: q.pop(0)
            else: break
        if not q: units[ui][:] = ['PASS']; continue
        op, tg = q[0]; p = pos[ui]
        inv = priv['inventories'][ui] if ui < len(priv['inventories']) else {}
        if op == 'FEED' and inv.get('WHEAT', 0) <= 0:
            sh = min(SHED_T, key=lambda z: _d(p, z))
            if p == sh:
                if priv['shed'].get('WHEAT', 0) > 0: units[ui][:] = ['PICKUP', 'WHEAT', 2]
                else: units[ui][:] = ['PASS']; need_wheat += 2
            else: units[ui][:] = _toward(p, sh)
            continue
        mv = _toward(p, tg)
        units[ui][:] = mv if mv else [op]
    if need_wheat and len(action['market']) < 10: action['market'].append(['BUY_PRODUCT', 'WHEAT', need_wheat])

def hire_fund(obs, action, acts, step):
    """If this step's HIRE orders exceed cash + the step's own sale proceeds, sell shed products (highest value first; wheat kept
    for one feed per animal plus the tape's same-day wheat needs) to cover the shortfall; sells go in front of the hires."""
    m = action['market']; nh = sum(1 for o in m if o[0] == 'HIRE')
    if not nh: return
    me = obs['farms'][obs['player']]; shed = dict(obs['private']['shed']); pr = obs['market']['prices']
    cost = sum(fib(me['hires_today'] + i) for i in range(nh))
    cash = me['money']
    for o in m:
        if o[0] == 'SELL' and len(o) > 2 and o[1] in pr:
            q = min(o[2], shed.get(o[1], 0)); shed[o[1]] = shed.get(o[1], 0) - q; cash += q * pr[o[1]]
    short = cost - cash
    if short <= 0: return
    na = sum(1 for r in me['tiles'] for t in r if isinstance(t, dict) and t.get('animal'))
    keep = {'WHEAT': int(na * P['HFUND_KEEP'].get('WHEAT', 1.0)) + 2, 'FERTILIZER': int(P['HFUND_KEEP'].get('FERTILIZER', 0))}
    add = []
    for p in sorted((p for p in ITEMS[:9] if shed.get(p, 0) > keep.get(p, 0) and pr.get(p, 0) >= 2), key=lambda p: -pr[p]):
        if short <= 0: break
        q = min(shed[p] - keep.get(p, 0), math.ceil(short / pr[p])); add.append(['SELL', p, q]); short -= q * pr[p]
    if add:
        k = next((i for i, o in enumerate(m) if o[0] == 'HIRE'), 0)
        action['market'] = (m[:k] + add + m[k:])[:10]; _log(f"s{step} hire fund {add} cost {cost} cash {cash:.0f}")

def cash_reserve(obs, action, step, acts):
    """Keep projected cash >= R after seed/animal purchases: R = R0 + tomorrow morning's tape hires (fib) + one day of feed.
    Seed/animal orders are truncated (the missed PLANT is re-planted later by the debt repair when DEBT is on)."""
    me = obs['farms'][obs['player']]; shed = obs['private']['shed']; pr = obs['market']['prices']; day = step // 24
    R = P['RES_R0']
    if P['RES_HIRE']:
        nxt = (day + 1) * 24; nh = sum(1 for s in range(nxt, min(nxt + 3, len(acts))) for o in acts[s][2] if o and o[0] == 'HIRE')
        if step % 24 < 3 and day * 24 + 3 > step:   # today's own hires still to come
            nh2 = sum(1 for s in range(step + 1, day * 24 + 3) for o in acts[s][2] if o and o[0] == 'HIRE')
            R += sum(fib(me['hires_today'] + i) for i in range(nh2))
        R += sum(fib(i) for i in range(nh))
    if P['RES_FEED']:
        na = sum(1 for r in me['tiles'] for t in r if isinstance(t, dict) and t.get('animal'))
        R += max(0, na - shed.get('WHEAT', 0)) * pr['WHEAT']
    cash = me['money']; sh = dict(shed); out = []
    for o in action['market']:
        op = o[0]
        if op == 'SELL' and len(o) > 2 and o[1] in pr:
            q = min(o[2], sh.get(o[1], 0)); sh[o[1]] = sh.get(o[1], 0) - q; cash += q * pr[o[1]] * (0.9 if o[1] not in ('WHEAT', 'FERTILIZER') else 1.0)
        elif op == 'HIRE': cash -= fib(me['hires_today'] + sum(1 for x in out if x[0] == 'HIRE'))
        elif op == 'BUY_LAND': cash -= [1000, 2000, 4000][min(2, len(me['unlocked_quadrants']) - 1)]
        elif op == 'BUY_PRODUCT' and len(o) > 2: cash -= o[2] * pr.get(o[1], 0); sh[o[1]] = sh.get(o[1], 0) + o[2]
        elif op in ('BUY_SEED', 'BUY_ANIMAL') and len(o) > 2:
            c = (SEED_COST if op == 'BUY_SEED' else ANIMAL_COST).get(o[1], 0)
            n = min(o[2], max(0, int((cash - R) // c))) if c else o[2]
            if n < o[2]: _log(f"s{step} reserve cut {o} to {n} cash {cash:.0f} R {R:.0f}")
            if n <= 0: continue
            o = [op, o[1], n]; cash -= n * c
        out.append(o)
    action['market'] = out

def enc_opp(obs):
    f = obs['farms'][1 - obs['player']]; flat = [t for r in f['tiles'] for t in r]
    return ''.join(tcode(t) for t in flat), [(-1 if not isinstance(t, dict) or t.get('kind') != 'PLANT' else t.get('planted_day', -1)) for t in flat]

def fingerprint(obs, day):
    """fable: is the opponent running a Boey-programme farm? Its day-start layout is compared with every library tape's layout on
    the same day (lenient distance); a match within FP_TOL on FP_DAYS sets the executor's BOEY_OPP flag."""
    if not P.get('FP') or day not in P['FP_DAYS'] or S.get('fp_done'): return
    tiles, pd = enc_opp(obs); L = [t for t in lib() if day < len(t['st'])]
    best = min((ldist(t, day, tiles, pd) for t in L), default=99.0)
    S.setdefault('fp_hist', []).append((day, round(best, 1)))
    if best <= P['FP_TOL']:
        S['fp_done'] = True; S['boey_opp'] = True; xc().P['BOEY_OPP'] = True; _log(f"d{day} FINGERPRINT Boey-programme opponent (ldist {best:.1f})")

def overlay_straw(obs, action, day):
    """fable OV_STRAW (leaders' d3-5 trade): the tape's animal purchases on OV_DAYS become strawberry seeds (up to OV_STRAW seeds
    bought), and while seeds are in stock the tape's BUILD_PASTURE/BUILD_COOP actions become PLANT STRAWBERRY on that tile; the
    tape's later PICKUP/PLACE/FEED/CARE on those tiles are engine no-ops, RESCUE waters the plants until the executor takes over."""
    seeds_now = obs['private'].get('seeds', {}).get('STRAWBERRY', 0)
    O = S.setdefault('ov', {'bought': 0, 'seeds_prev': None, 'planted': 0})
    if O['seeds_prev'] is not None and seeds_now > O['seeds_prev']: O['bought'] += seeds_now - O['seeds_prev']
    if day in P['OV_DAYS'] and O['bought'] < P['OV_STRAW']:
        m = action['market']; k = 0
        for i, o in enumerate(m):
            if o and o[0] == 'BUY_ANIMAL' and o[1] in P['OV_KINDS'] and k < 1:
                m[i] = ['BUY_SEED', 'STRAWBERRY', 1]; k += 1
            elif o and o[0] == 'BUY_ANIMAL' and o[1] in P['OV_KINDS']:
                m[i] = None
        action['market'] = [o for o in m if o]
    units = [action['farmer']] + action['hands']
    avail = seeds_now
    if avail > 0 and O['planted'] < P['OV_STRAW']:
        for u in units:
            if avail <= 0: break
            if u and u[0] in ('BUILD_PASTURE', 'BUILD_COOP'):
                u[:] = ['PLANT', 'STRAWBERRY']; avail -= 1; O['planted'] += 1; _log(f"d{day} OV plant strawberry instead of {u}")
    O['seeds_prev'] = seeds_now - (seeds_now - avail)   # seeds after this step's plantings (the step's own seed buy lands after)

def tape_action(obs, step):
    hour = step % 24; day = step // 24; known = list(obs['town']['unlocked_shops'])
    if hour == 0 and day >= 1: fingerprint(obs, day)
    if 'tape' not in S:
        S['tape'] = choose0(); S['picks'] = [(step, S['tape']['ep'])]
    elif hour == 0 and day in P['SWITCH_DAYS']:
        t, sc, n = choose(obs, day, known, S['tape'])
        if t['ep'] != S['tape']['ep']: S['picks'].append((step, t['ep']))
        if P['LOG']:
            tl, pdl, _ = enc(obs); tt, tp, _ = S['tape']['st'][day]
            _log(f"d{day} mism cur {[(i, tl[i], tt[i], pdl[i], tp[i]) for i in range(100) if tl[i] != tt[i] or (pdl[i] >= 0 and pdl[i] != tp[i])]}")
        _log(f"d{day} switch cands {n} pick {t['ep']} score {sc} known {known} tape shops {t['shops'][:len(known)+1]}")
        S['tape'] = t
    if hour == 0 and P['LOG'] and day >= 1:
        tl, pdl, mo = enc(obs); t = S['tape']
        _log(f"H0 d{day} ldist {ldist(t, day, tl, pdl):.1f} money {mo:.0f} tape {t['st'][day][2]} hands_prev {S.get('nh_prev')} tape_hands_prev {S.get('th_prev')}")
    acts = acts_of(S['tape'])
    n_hands = len(obs['farms'][obs['player']].get('hands', []))
    fa, ha, ma = acts[step]
    if hour == 12: S['nh_prev'] = n_hands; S['th_prev'] = len(ha)
    action = {'farmer': list(fa) if fa else ['PASS'], 'hands': [list(x) if x else ['PASS'] for x in ha], 'market': [list(x) for x in ma if x]}
    if P['NET']: action['market'] = net_orders(action['market'])
    if len(action['hands']) < n_hands: action['hands'] += [['PASS']] * (n_hands - len(action['hands']))
    action['hands'] = action['hands'][:n_hands]
    if P['OV_STRAW'] and day <= max(P['OV_DAYS']) + 1: overlay_straw(obs, action, day)
    if P['PLANT_TRIM']: repair(obs, action, day)
    if P['LAND_RETRY'] or P['ACAP']: overlay(obs, action, step, acts, known)
    if P['HFIRST']:
        m = action['market']; sells = [o for o in m if o[0] == 'SELL']; hires = [o for o in m if o[0] == 'HIRE']
        action['market'] = sells + hires + [o for o in m if o[0] not in ('SELL', 'HIRE')]
    if P['HFUND']: hire_fund(obs, action, acts, step)
    if P['RES'] and day >= P['RES_FROM_DAY']: cash_reserve(obs, action, step, acts)
    if P['RESCUE'] and hour >= P['RESCUE_HOUR']:
        try: rescue(obs, action, step, acts)
        except Exception as ex: _log(f'rescue err {ex!r}')
    if P['GUARD']:
        try: budget_guard(obs, action, step, acts)
        except Exception as ex: _log(f'guard err {ex!r}')
    return action

def _pass(obs):
    try: n = len(obs['farms'][obs['player']].get('hands', []))
    except Exception: n = 0
    return {'farmer': ['PASS'], 'hands': [['PASS']] * n, 'market': []}

def agent(obs, config=None):
    step = int(obs.get('step', 0))
    if step == 0:
        S.clear(); x = xc(); x.S.clear(); x.P['BOEY_OPP'] = False; x.P.update(_G['xcp']); x.P.update(P.get('XC_P', {}))
    if step >= P['HANDOVER']:
        if not S.get('handed'): S['handed'] = True; xc().S.clear()
        return xc().safe_agent(obs, config)
    try: return tape_action(obs, step)
    except Exception as ex:
        _log(f'err {step} {ex!r}')
        return _pass(obs)

